#!/data/data/com.termux/files/usr/bin/bash
set -e

BUILD_FILE="app/build.gradle.kts"
VIDEOUTILS="app/src/main/java/com/android/gallery3d/app/VideoUtils.java"

echo "== Reescrevendo app/build.gradle.kts com deps corretas e nonFinalResIds desligado =="

APPLICATION_ID="com.xaulinxs.galeria3d"

cat > "$BUILD_FILE" << EOF
plugins {
    id("com.android.application")
}

android {
    namespace = "com.android.gallery3d"
    compileSdk = 34

    defaultConfig {
        applicationId = "$APPLICATION_ID"
        minSdk = 21
        targetSdk = 34
        versionCode = 1
        versionName = "1.0"
    }

    sourceSets["main"].java.srcDirs("src/main/java")
    sourceSets["main"].res.srcDirs("src/main/res")
    sourceSets["main"].manifest.srcFile("src/main/AndroidManifest.xml")

    buildTypes {
        release {
            isMinifyEnabled = false
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

dependencies {
    implementation("androidx.core:core:1.13.1")
    implementation("androidx.fragment:fragment:1.8.2")
    implementation("androidx.legacy:legacy-support-v13:1.0.0")
    implementation("androidx.legacy:legacy-support-core-ui:1.0.0")
    implementation("com.googlecode.mp4parser:isoparser:1.1.22")
    implementation("com.adobe.xmp:xmpcore:6.1.11")
}
EOF

echo "== Adicionando android.nonFinalResIds=false ao gradle.properties =="
if grep -q "android.nonFinalResIds" gradle.properties 2>/dev/null; then
  sed -i 's/android.nonFinalResIds=.*/android.nonFinalResIds=false/' gradle.properties
else
  echo "android.nonFinalResIds=false" >> gradle.properties
fi

echo "== Restaurando VideoUtils.java compativel com isoparser 1.1.22 =="
mkdir -p "$(dirname "$VIDEOUTILS")"
base64 -d > "$VIDEOUTILS" << 'B64_EOF'

B64_EOF

echo "== Conferindo tamanho do VideoUtils.java reescrito =="
wc -l "$VIDEOUTILS"

echo "== Fix concluido =="
